const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Commercial property lease escalation and tax calculator. Applies annual compound escalation rates, computes Section 194I TDS deductions, statutory 18% GST invoice amounts, and security deposit adjustments.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"leaseId":"LEASE-COMM-2024-08","unitId":"Retail Unit G-02","currentMonthlyRent":85000,"escalationPercentage":5,"escalatedMonthlyRent":89250,"effectiveFrom":"2026-12-01","taxBreakdown":{"baseRent":89250,"gstRate":18,"gstAmount":16065,"tdsRate":10,"tdsDeduction":8925,"netPayableByTenant":96390},"depositAdjustmentRequired":25500,"statutoryNotes":"Commercial rental attracts 18% GST under SAC 997212. TDS deduction under Section 194-I applies at 10% for corporate entities."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"leaseId":"LEASE-COMM-2024-08","unitId":"Retail Unit G-02","currentMonthlyRent":85000,"escalationPercentage":5,"escalatedMonthlyRent":89250,"effectiveFrom":"2026-12-01","taxBreakdown":{"baseRent":89250,"gstRate":18,"gstAmount":16065,"tdsRate":10,"tdsDeduction":8925,"netPayableByTenant":96390},"depositAdjustmentRequired":25500,"statutoryNotes":"Commercial rental attracts 18% GST under SAC 997212. TDS deduction under Section 194-I applies at 10% for corporate entities."} } }];
}
